using System;

namespace Tsumo.Cli
{
    public static class Node_modules_Tsumo_engine_src_config_scalars
    {
        public static Func<string, string, string?, int, ParamValue> parseScalarText
        {
            get;
            private set;
        } = default(Func<string, string, string?, int, ParamValue>)!;
        public static Func<string, string, string?, int, ParamValue> parseConfigParam
        {
            get;
            private set;
        } = default(Func<string, string, string?, int, ParamValue>)!;
        public static Func<string, string, string, string?, int, string> parseConfigString
        {
            get;
            private set;
        } = default(Func<string, string, string, string?, int, string>)!;
        public static Func<string, string, string, string?, int, int> parseConfigInt
        {
            get;
            private set;
        } = default(Func<string, string, string, string?, int, int>)!;
        private static readonly System.Lazy<object?> __tsonic_module_initialization = new System.Lazy<object?>(() => __tsonic_module_init_core());
        private static object? __tsonic_module_init_core()
        {
            Node_modules_Tsumo_engine_src_params.__tsonic_module_init();
            Node_modules_Tsumo_engine_src_utils_structuredScalars.__tsonic_module_init();
            parseScalarText = (string value, string format, string? sourcePath, int line) =>
            {
                return Node_modules_Tsumo_engine_src_utils_structuredScalars.parseStructuredScalar(value, format, (string message) => Node_modules_Tsumo_engine_src_diagnostics.createTsumoError("TSUMO_CONFIG_SYNTAX_INVALID", message, sourcePath, line, 1));
            };
            parseConfigParam = (string value, string format, string? sourcePath, int line) => parseScalarText(value, format, sourcePath, line);
            parseConfigString = (string field, string value, string format, string? sourcePath, int line) =>
            {
                ParamValue parsed = parseScalarText(value, format, sourcePath, line);
                if (parsed.kind == ParamKind.String)
                {
                    return parsed.stringValue;
                }
                throw Node_modules_Tsumo_engine_src_diagnostics.createTsumoError("TSUMO_CONFIG_INVALID_FIELD", $"Configuration field '{field}' requires a string", sourcePath, line, 1);
            };
            parseConfigInt = (string field, string value, string format, string? sourcePath, int line) =>
            {
                ParamValue parsed = parseScalarText(value, format, sourcePath, line);
                if (parsed.kind == ParamKind.Number)
                {
                    return parsed.numberValue;
                }
                throw Node_modules_Tsumo_engine_src_diagnostics.createTsumoError("TSUMO_CONFIG_INVALID_FIELD", $"Configuration field '{field}' requires a 32-bit integer", sourcePath, line, 1);
            };
            return null;
        }
        public static void __tsonic_module_init()
        {
            _ = __tsonic_module_initialization.Value;
        }
    }
}
